static int cmd_add(int argc, char **argv)
{
    long n;

    if (argc < 1) {
        fprintf(stderr, "add: needs an argument\n");
        return 2;
    }
    n = store_add(argv[0]);
    if (n < 0) {
        fprintf(stderr, "add: failed\n");
        return 1;
    }
    printf("add ok=1 n=%ld\n", n);
    return 0;
}


struct entry { const char *name; int (*fn)(int, char **); };

static const struct entry table[] = {
    { "add", cmd_add },
    { NULL, NULL }
